// Parse inbound email — Mailgun-style schema by default; adapt the field names for Postmark/SendGrid.
// Fields are typically: sender, recipient, subject, body-plain, body-html, Message-Id.
const body = $input.first().body;

const from = body.sender || body.from || body.From || '';
const subject = body.subject || body.Subject || '';
const bodyText = body['body-plain'] || body.text || body['stripped-text'] || '';

// Naive but effective contact extraction
const emailMatch = from.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}/);
const nameMatch = from.replace(/<[^>]+>/g, '').trim().replace(/^"|"$/g, '');
const phoneMatch = bodyText.match(/(?:\+?\d{1,3}[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}/);

// Intent classification
const keywords = ($node['SET_DEFAULTS'].json['high_priority_keywords'] || '').toLowerCase().split(',');
const haystack = (subject + ' ' + bodyText).toLowerCase();
const matchedKeywords = keywords.filter(k => k && haystack.includes(k));
const priority = matchedKeywords.length > 0 ? 'high' : 'normal';

return [{
  json: {
    contact_name: nameMatch || 'unknown',
    contact_email: emailMatch ? emailMatch[0] : '',
    contact_phone: phoneMatch ? phoneMatch[0] : '',
    subject,
    body_excerpt: bodyText.slice(0, 500),
    priority,
    matched_keywords: matchedKeywords,
    received_at: new Date().toISOString()
  }
}];

